// Isolation test (OS-12) — construct DifficultyAdvisory with its declared inputs and nothing else, then
// exercise every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { noSubject } from "../src/kernel/index.js";
import type { Unit } from "../src/catalog/index.js";
import { DifficultyAdvisory, PLAIN_DIFFICULTY, type FeatureSource } from "../src/advisory/index.js";

const u = "u1" as Unit;
const units: FeatureSource = { features: () => ({ parts: 3 }) };

describe("DifficultyAdvisory in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new DifficultyAdvisory({ rule: PLAIN_DIFFICULTY } as never)).toThrow();
    expect(() => new DifficultyAdvisory({ units } as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new DifficultyAdvisory({ units: {} as never, rule: PLAIN_DIFFICULTY })).toThrow();
    expect(() => new DifficultyAdvisory({ units, rule: {} as never })).toThrow();
  });

  it("advisory answers differently when units differs", () => {
    expect(new DifficultyAdvisory({ units, rule: PLAIN_DIFFICULTY }).advisory(u)).not.toEqual(new DifficultyAdvisory({ units: { features: () => noSubject() }, rule: PLAIN_DIFFICULTY }).advisory(u));
  });

  it("advisory answers differently when rule differs", () => {
    expect(new DifficultyAdvisory({ units, rule: PLAIN_DIFFICULTY }).advisory(u)).not.toEqual(new DifficultyAdvisory({ units, rule: { assess: () => ({ parts: 9 }) } }).advisory(u));
  });
});
